import json
import requests
import chardet
API_URL = "http://api.example.com/data"
def task_func(url=API_URL, from_encoding=None, to_encoding="utf8"):
    response = requests.get(url, timeout=5)
    content = response.content or b""
    if not content:
        return {}
    src_enc = from_encoding or response.encoding
    if not src_enc:
        det = chardet.detect(content) or {}
        src_enc = det.get("encoding")
    if not src_enc:
        raise ValueError("Unable to detect encoding for non-empty content")
    try:
        text = content.decode(src_enc)
    except Exception:
        text = content.decode(src_enc, errors="replace")
    try:
        recoded_bytes = text.encode(to_encoding)
    except Exception:
        recoded_bytes = text.encode(to_encoding, errors="replace")
    try:
        normalized = recoded_bytes.decode(to_encoding)
    except Exception:
        normalized = recoded_bytes.decode(to_encoding, errors="replace")
    if normalized.startswith("\ufeff"):
        normalized = normalized.lstrip("\ufeff")
    data = json.loads(normalized)
    return data
