1. Parse the input JSON string into a Python dictionary; if parsing fails, return an empty dict.
2. Traverse all string content within the dict, including nested lists and dictionaries, and consider string keys and values.
3. Use a specific URL pattern to find all http and https URLs within the collected strings.
4. Count occurrences of each URL and return the top N most frequent URLs as a dictionary.

### code
```python
import re
import json
from collections import Counter
def task_func(json_str, top_n=10):
    try:
        data = json.loads(json_str)
    except json.JSONDecodeError:
        return {}
    def iter_strings(obj):
        if isinstance(obj, str):
            yield obj
        elif isinstance(obj, dict):
            for k, v in obj.items():
                if isinstance(k, str):
                    yield k
                yield from iter_strings(v)
        elif isinstance(obj, list):
            for item in obj:
                yield from iter_strings(item)
        elif isinstance(obj, (int, float, bool)) or obj is None:
            return
        else:
            yield str(obj)
    pattern = re.compile(r'https?://[^\s"\'<>()]+')
    matches = []
    for s in iter_strings(data):
        matches.extend(pattern.findall(s))
    counts = Counter(matches)
    if top_n is None:
        return dict(counts)
    return dict(counts.most_common(top_n))
```

