import re
import json
# Constants
IP_REGEX = r'[0-9]+(?:\.[0-9]+){3}'
def task_func(ip_address):
    def find_ip(obj):
        if isinstance(obj, dict):
            for v in obj.values():
                r = find_ip(v)
                if r:
                    return r
        elif isinstance(obj, list):
            for v in obj:
                r = find_ip(v)
                if r:
                    return r
        elif isinstance(obj, (str, int, float)):
            s = str(obj)
            m = re.search(IP_REGEX, s)
            if m:
                return m.group(0)
        return None
    def is_valid(ip):
        if not re.fullmatch(IP_REGEX, ip):
            return False
        parts = ip.split('.')
        for p in parts:
            try:
                n = int(p)
            except:
                return False
            if n < 0 or n > 255:
                return False
        return True
    if isinstance(ip_address, str):
        try:
            data = json.loads(ip_address)
        except:
            m = re.search(IP_REGEX, ip_address)
            ip = m.group(0) if m else None
            return ip if ip and is_valid(ip) else 'Invalid IP address received'
    else:
        data = ip_address
    ip = find_ip(data)
    return ip if ip and is_valid(ip) else 'Invalid IP address received'
