import pandas as pd
import os
import json
from collections import Counter
def task_func(json_dir_path, word_count):
    if not os.path.isdir(json_dir_path):
        return []
    words = []
    def extract_strings(obj):
        if isinstance(obj, str):
            return [obj]
        if isinstance(obj, dict):
            res = []
            for v in obj.values():
                res.extend(extract_strings(v))
            return res
        if isinstance(obj, list):
            res = []
            for item in obj:
                res.extend(extract_strings(item))
            return res
        return []
    for filename in os.listdir(json_dir_path):
        if filename.lower().endswith('.json'):
            path = os.path.join(json_dir_path, filename)
            try:
                with open(path, 'r', encoding='utf-8') as f:
                    data = json.load(f)
            except Exception:
                continue
            for s in extract_strings(data):
                cleaned = s.lower()
                cleaned = ''.join(ch if (ch.isalnum() or ch.isspace()) else ' ' for ch in cleaned)
                words.extend([w for w in cleaned.split() if w])
    counter = Counter(words)
    return counter.most_common(int(word_count))
