import cgi
import http.server
import json
SUCCESS_RESPONSE = {
    'status': 'success',
    'message': 'Data received successfully.'
}
ERROR_RESPONSE = {
    'status': 'error',
    'message': 'Invalid data received.'
}
def task_func():
    class RequestHandler(http.server.BaseHTTPRequestHandler):
        def _send_json(self, status_code, payload):
            body = json.dumps(payload).encode('utf-8')
            self.send_response(status_code)
            self.send_header('Content-Type', 'application/json')
            self.send_header('Content-Length', str(len(body)))
            self.end_headers()
            self.wfile.write(body)
        def do_POST(self):
            ctype = self.headers.get('Content-Type', '')
            if (ctype or '').strip().lower() != 'application/json':
                payload = dict(ERROR_RESPONSE)
                payload['message'] = 'Content-Type header is not application/json'
                return self._send_json(400, payload)
            try:
                length = int(self.headers.get('Content-Length', '0'))
            except ValueError:
                length = 0
            body = self.rfile.read(length) if length > 0 else b''
            try:
                data = json.loads(body.decode('utf-8') if body else '{}')
            except json.JSONDecodeError:
                payload = dict(ERROR_RESPONSE)
                payload['message'] = 'Invalid JSON'
                return self._send_json(400, payload)
            if 'data' not in data:
                payload = dict(ERROR_RESPONSE)
                payload['message'] = 'No data key in request'
                return self._send_json(400, payload)
            return self._send_json(200, SUCCESS_RESPONSE)
    return RequestHandler
