```python
import json
import re
import pandas as pd
def task_func(json_str):
    if not isinstance(json_str, str) or not json_str.strip():
        return pd.DataFrame()
    try:
        data = json.loads(json_str)
    except Exception:
        return pd.DataFrame()
    if not isinstance(data, dict) or not data:
        return pd.DataFrame()
    pattern = re.compile(r'[-+]?\d*\.?\d+(?:[eE][-+]?\d+)?')
    def parse_string_to_float(s):
        matches = pattern.findall(s)
        if matches:
            try:
                return float(matches[0]) * 2.0
            except Exception:
                return s
        return s
    def normalize_value(v):
        if isinstance(v, bool):
            return v
        if isinstance(v, (int, float)):
            return float(v) * 2.0
        if isinstance(v, str):
            return parse_string_to_float(v)
        if isinstance(v, list):
            out = []
            for item in v:
                if isinstance(item, bool):
                    out.append(item)
                elif isinstance(item, (int, float)):
                    out.append(float(item) * 2.0)
                elif isinstance(item, str):
                    out.append(parse_string_to_float(item))
                else:
                    out.append(item)
            return out
        return v
    norm = {k: normalize_value(v) for k, v in data.items()}
    list_keys = [k for k, v in norm.items() if isinstance(v, list)]
    scalar_keys = [k for k, v in norm.items() if not isinstance(v, list) and not isinstance(v, dict)]
    if list_keys and scalar_keys:
        return pd.DataFrame()
    if list_keys:
        lengths = [len(norm[k]) for k in list_keys]
        if not lengths:
            return pd.DataFrame()
        s = set(lengths)
        if len(s) != 1:
            return pd.DataFrame()
        n = next(iter(s))
        if n == 0:
            return pd.DataFrame()
        return pd.DataFrame({k: norm[k] for k in list_keys})
    if scalar_keys:
        return pd.DataFrame([{k: norm[k] for k in scalar_keys}])
    return pd.DataFrame()
