    if not isinstance(data, dict):
        return pd.DataFrame()
    num_pattern = re.compile(r'[-+]?\d*\.?\d+(?:[eE][-+]?\d+)?')
    def process_string(s):
        nums = num_pattern.findall(s)
        if not nums:
            return s
        if len(nums) == 1 and s.strip() == nums[0]:
            return float(nums[0]) * 2.0
        return [float(n) * 2.0 for n in nums]
    def process_value(v):
