            out = []
            for item in v:
                if isinstance(item, (int, float)):
                    out.append(float(item) * 2.0)
                elif isinstance(item, str):
                    m = num_pattern.fullmatch(item.strip())
                    if m:
                        out.append(float(m.group()) * 2.0)
                    else:
                        out.append(item)
                else:
                    out.append(item)
            return out
        return None
    normalized = {}
    for k, v in data.items():
        nv = process_value(v)
        if nv is not None:
            normalized[k] = nv
    if not normalized:
        return pd.DataFrame()
    try:
        if normalized and all(isinstance(val, list) for val in normalized.values()):
            try:
                df = pd.DataFrame(normalized)
            except Exception:
                df = pd.DataFrame([normalized])
        else:
            df = pd.DataFrame([normalized])
    except Exception:
        df = pd.DataFrame()
