import json
import csv
import os
import base64
def task_func(raw_string, filename, output_dir):
    if not os.path.exists(output_dir):
        os.makedirs(output_dir, exist_ok=True)
    file_path = os.path.join(output_dir, filename if filename.lower().endswith('.csv') else filename + '.csv')
    data = None
    try:
        decoded_bytes = base64.b64decode(raw_string)
        decoded_str = decoded_bytes.decode('utf-8')
        data = json.loads(decoded_str)
    except Exception:
        data = None
    with open(file_path, 'w', newline='', encoding='utf-8') as f:
        writer = csv.writer(f)
        def to_str(v):
            if isinstance(v, (dict, list)):
                return json.dumps(v, ensure_ascii=False)
            return '' if v is None else str(v)
        if data is None:
            pass
        elif isinstance(data, list):
            if not data:
                pass
            else:
                dict_items = [x for x in data if isinstance(x, dict)]
                non_dict_items = [x for x in data if not isinstance(x, dict)]
                keys_order = []
                for item in dict_items:
                    for k in item.keys():
                        if k not in keys_order:
                            keys_order.append(k)
                if non_dict_items and not keys_order:
                    writer.writerow(['value'])
                    for item in non_dict_items:
                        writer.writerow([to_str(item)])
                else:
                    header = keys_order + (['value'] if non_dict_items else [])
                    writer.writerow(header)
                    for item in data:
                        if isinstance(item, dict):
                            row = [item.get(k, '') for k in keys_order]
                            if non_dict_items:
                                row.append('')
                            writer.writerow(row)
                        else:
                            row = ([''] * len(keys_order)) + [to_str(item)]
                            writer.writerow(row)
        elif isinstance(data, dict):
            keys_order = list(data.keys())
            writer.writerow(keys_order)
            writer.writerow([data.get(k, '') for k in keys_order])
        else:
            writer.writerow(['value'])
            writer.writerow([to_str(data)])
    return os.path.abspath(file_path)

