                if all(isinstance(item, dict) for item in data):
                    headers = []
                    seen = set()
                    for item in data:
                        for k in item.keys():
                            if k not in seen:
                                seen.add(k)
                                headers.append(k)
                    writer.writerow(headers)
                    for item in data:
                        row = [format_val(item.get(h, '')) for h in headers]
                        writer.writerow(row)
                elif all(isinstance(item, (list, tuple)) for item in data):
                    for item in data:
                        writer.writerow([format_val(v) for v in item])
                else:
                    writer.writerow(['value'])
                    for item in data:
                        writer.writerow([format_val(item)])
        elif isinstance(data, dict):
            headers = list(data.keys())
            writer.writerow(headers)
            row = [format_val(data.get(h)) for h in headers]
            writer.writerow(row)
        else:
            writer.writerow(['value'])
            writer.writerow([format_val(data)])
    return os.path.abspath(file_path)
