import json
import re
from collections import Counter
# Constants
REPLACE_NONE = "None"
def task_func(json_str):
    try:
        data = json.loads(json_str)
    except json.JSONDecodeError:
        return {"data": {}, "value_counts": Counter()}
    email_pattern = re.compile(r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b')
    def replace_emails(s):
        return email_pattern.sub(REPLACE_NONE, s)
    def clean(obj):
        if isinstance(obj, dict):
            res = {}
            for k, v in obj.items():
                if v is None:
                    continue
                res[k] = clean(v)
            return res
        if isinstance(obj, list):
            res = []
            for item in obj:
                if item is None:
                    continue
                res.append(clean(item))
            return res
        if isinstance(obj, str):
            return replace_emails(obj)
        return obj
    def gather_values(obj, acc):
        if isinstance(obj, dict):
            for v in obj.values():
                gather_values(v, acc)
        elif isinstance(obj, list):
            for item in obj:
                gather_values(item, acc)
        else:
            if obj is not None:
                acc.append(obj)
    processed = clean(data)
    values = []
    gather_values(processed, values)
    counts = Counter(values)
    return {"data": processed, "value_counts": counts}

