import json
import re
from collections import Counter
REPLACE_NONE = "None"
def task_func(json_str):
    try:
        data = json.loads(json_str)
    except Exception:
        return {"data": {}, "value_counts": Counter()}
    email_re = re.compile(r'(?i)\b[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}\b')
    def process(obj):
        if isinstance(obj, dict):
            return {k: process(v) for k, v in obj.items() if v is not None}
        if isinstance(obj, list):
            return [process(v) for v in obj if v is not None]
        if isinstance(obj, str):
            return email_re.sub(REPLACE_NONE, obj)
        return obj
    processed = process(data)
    flat_values = []
