        if isinstance(obj, dict):
            for v in obj.values():
                collect(v)
        elif isinstance(obj, list):
            for v in obj:
                collect(v)
        else:
            flat_values.append(obj)
    collect(processed)
    counts = Counter(flat_values)
    return {"data": processed, "value_counts": counts}
