import json
import pandas as pd
from sklearn.preprocessing import MinMaxScaler
import matplotlib.pyplot as plt
def task_func(json_data: str, data_key: str):
    def get_by_path(obj, path):
        current = obj
        for part in path.split('.'):
            if isinstance(current, dict):
                if part in current:
                    current = current[part]
                else:
                    raise KeyError(path)
            elif isinstance(current, list):
                try:
                    idx = int(part)
                    current = current[idx]
                except Exception:
                    raise KeyError(path)
            else:
                raise KeyError(path)
        return current

    def extract_numeric(obj):
        out = []
        def rec(x):
            if isinstance(x, dict):
                for v in x.values():
                    rec(v)
            elif isinstance(x, (list, tuple)):
                for v in x:
                    rec(v)
            elif isinstance(x, (int, float)):
                out.append(float(x))
            elif isinstance(x, str):
                try:
                    out.append(float(x.strip()))
                except Exception:
                    pass
        rec(obj)
        return out

    data = json.loads(json_data)
    target = get_by_path(data, data_key)
    nums = extract_numeric(target)
    original_series = pd.Series(nums, dtype='float64')
    if original_series.empty:
        return original_series, None, None
    scaler = MinMaxScaler()
    norm_vals = scaler.fit_transform([[v] for v in original_series.tolist()])
    normalized_series = pd.Series([float(v[0]) for v in norm_vals], dtype='float64')
    fig, ax = plt.subplots()
    ax.plot(range(len(original_series)), original_series.tolist(), label="Original Data")
    ax.plot(range(len(normalized_series)), normalized_series.tolist(), label="Normalized Data")
    ax.set_title("Comparison of Original and Normalized Data")
    ax.set_xlabel("Index")
    ax.set_ylabel("Value")
    ax.legend()
    return original_series, normalized_series, ax
